#!/usr/bin/env bash
# Round cap for prp-review-agents (prp-framework#151 AC3).
#
# Invariant: every stdin line classifies as exactly one of EXACT (matches RUN_RE, counted), SHAPED
# (footer-shaped but not exact, refuses exit 2) or OTHER (ignored). Every line carrying a footer's
# identifying parts -- the "generated by" + "prp-review-agents" pair in either order, a line starting
# with the "prp-review-agents v<digit>" tail, or run=<id> together with pass= -- is EXACT or SHAPED,
# never OTHER, so a mangled footer can never lower the count. Out of scope: a line with none of those
# parts (e.g. only `pass=code-reviewer`) is OTHER.
#
# usage: round-guard.sh [--cap N] < footer-lines
#   stdin: one line per PR comment = that comment's LAST line (the caller extracts it).
#   exit 0 = allowed (prints "rounds so far: R of N; this is round R+1")
#   exit 3 = refused: cap reached
#   exit 2 = unparseable footer, bad argument, or unreadable input (fail closed)
set -euo pipefail

CAP=10
while [[ $# -gt 0 ]]; do
  case "$1" in
    --cap) [[ $# -ge 2 ]] || { echo "error: --cap needs a value" >&2; exit 2; }; CAP="$2"; shift 2 ;;
    *) echo "error: unknown argument '$1'" >&2; exit 2 ;;
  esac
done
printf '%s' "$CAP" | grep -qxE '[0-9]{1,3}' && [[ "$CAP" =~ ^[0-9]+$ ]] && (( 10#$CAP >= 1 )) \
  || { echo "error: --cap must be a number from 1 to 999" >&2; exit 2; }
CAP=$((10#$CAP))

RUN_RE='^Generated-by: prp-review-agents v[^ ]+ run=([0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}) pass=[a-z-]+( tier=trivial)?$'
# Footer shape, matched on the lower-cased line. A line with a footer's identifying parts that is not an exact
# footer refuses (exit 2): the "generated by" + "prp-review-agents" pair in either order (any 0-3 separator chars),
# the "prp-review-agents v<digit>" tail at line start (a footer split over two lines), or run=<id> together with
# pass=. L2 markers and prose that cite run ids have none of these, so they stay ignored.
SEP='[^a-z0-9]{0,3}'
SHAPE_RE="generated${SEP}by${SEP}prp-review-agents|prp-review-agents${SEP}generated${SEP}by|^[^a-z0-9]*prp-review-agents v[0-9]|run=[0-9]{8}t[0-9]{6}z-[0-9a-f]+.*pass=|pass=[a-z-]+.*run=[0-9]{8}t[0-9]{6}z-"
IDS=""
while IFS= read -r line || [[ -n "$line" ]]; do
  if [[ "$line" =~ $RUN_RE ]]; then
    IDS+="${BASH_REMATCH[1]}"$'\n'
  elif [[ "${line,,}" =~ $SHAPE_RE ]]; then
    echo "error: cannot parse a review footer — round count unknown, refusing" >&2
    exit 2
  fi
done
R=0
[[ -n "$IDS" ]] && R=$(printf '%s' "$IDS" | sort -u | wc -l | tr -d ' ')

if (( R >= CAP )); then
  echo "ROUND-CAP: refused — this PR already has $R review runs (cap $CAP). Review stop rule: fix open Critical/Important findings or re-route the work; file Medium/Low in ONE follow-up issue; do not start another round; escalate (delegate_or_escalate)." >&2
  exit 3
fi
echo "rounds so far: $R of $CAP; this is round $((R + 1))"
